1	/**
2	 * Plan changes and quota arithmetic. The single reader of `PLAN_LIMITS` on the server; every other layer asks this service.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, getPlanLimits, wouldExceedLimit, getLimit
5	 */
6	import {
7	  getLimit,
8	  getPlanLimits,
9	  wouldExceedLimit,
10	} from "@/config/plan-limits";
11	import { emit } from "@/lib/event-bus";
12	import { assertCan } from "@/lib/permissions";
13	import { assertOrgScope } from "@/lib/tenant";
14	import * as invoiceRepo from "@/server/repositories/invoice-repository";
15	import * as orgRepo from "@/server/repositories/organization-repository";
16	import * as subscriptionRepo from "@/server/repositories/subscription-repository";
17	import * as usageRepo from "@/server/repositories/usage-repository";
18	import * as webhookRepo from "@/server/repositories/webhook-repository";
19	import { toIsoTimestamp } from "@/types/common";
20	import { actorEnvelope, billingResource, requireFound } from "./_support";
21	import type {
22	  CancelSubscriptionInput,
23	  ChangePlanInput,
24	  UpdateSeatsInput,
25	} from "@/schemas/billing";
26	import type {
27	  BillingSummary,
28	  Invoice,
29	  LimitCheck,
30	  LimitedResource,
31	  PlanId,
32	  Subscription,
33	} from "@/types/billing";
34	import type { OrgId } from "@/types/common";
35	import type { Actor } from "@/types/member";
36	
37	/** The dimensions the billing page shows a meter for. */
38	const SUMMARY_RESOURCES: readonly LimitedResource[] = [
39	  "seats",
40	  "projects",
41	  "storageMb",
42	  "webhooks",
43	];
44	
45	export async function getBillingSummary(
46	  actor: Actor,
47	  orgId: OrgId,
48	): Promise<BillingSummary> {
49	  assertOrgScope(actor, orgId);
50	  assertCan(actor, "org:manage_billing", billingResource(orgId));
51	
52	  const subscription = requireFound(
53	    await subscriptionRepo.findSubscription(orgId),
54	    "Subscription",
55	    orgId,
56	  );
57	
58	  const checks = await Promise.all(
59	    SUMMARY_RESOURCES.map((resource) => checkLimit(orgId, resource, 0)),
60	  );
61	
62	  const limits = getPlanLimits(subscription.plan);
63	
64	  return {
65	    orgId,
66	    subscription,
67	    checks,
68	    upcomingInvoiceCents:
69	      limits.priceCentsPerSeatMonthly *
70	      subscription.seats *
71	      (subscription.interval === "annual" ? 12 : 1),
72	  };
73	}
74	
75	/**
76	 * The one place a quota is evaluated. Every guard elsewhere calls this rather
77	 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
78	 * exactly two files: `plan-limits.ts` and `usageFor()` below.
79	 */
80	export async function checkLimit(
81	  orgId: OrgId,
82	  resource: LimitedResource,
83	  requested = 1,
84	): Promise<LimitCheck> {
85	  const plan = await planFor(orgId);
86	  const used = await usageFor(orgId, resource);
87	  const limit = getLimit(plan, resource);
88	
89	  return {
90	    resource,
91	    plan,
92	    limit,
93	    used,
94	    remaining: Math.max(0, limit - used),
95	    exceeded: wouldExceedLimit(plan, resource, used, requested),
96	  };
97	}
98	
99	/** Throwing form used by the create paths, and it emits the breach event. */
100	export async function assertWithinLimit(
101	  orgId: OrgId,
102	  resource: LimitedResource,
103	  requested = 1,
104	): Promise<void> {
105	  const check = await checkLimit(orgId, resource, requested);
106	  if (!check.exceeded) return;
107	
108	  await emit("billing.limit_exceeded", {
109	    orgId,
110	    actorId: null,
111	    occurredAt: toIsoTimestamp(new Date()),
112	    resource,
113	    limit: check.limit,
114	    used: check.used,
115	  });
116	
117	  throw new Error(
118	    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
119	  );
120	}
121	
122	/**
123	 * A downgrade is refused while the org is over the target plan's quota — the
124	 * alternative is silently breaking their workspace at the next write.
125	 */
126	export async function changePlan(
127	  actor: Actor,
128	  input: ChangePlanInput,
129	): Promise<Subscription> {
130	  assertOrgScope(actor, input.orgId);
131	  assertCan(actor, "org:manage_billing", billingResource(input.orgId));
132	
133	  const currentPlan = await planFor(input.orgId);
134	
135	  for (const resource of SUMMARY_RESOURCES) {
136	    const used = await usageFor(input.orgId, resource);
137	    if (wouldExceedLimit(input.plan, resource, used, 0)) {
138	      throw new Error(
139	        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
140	      );
141	    }
142	  }
143	
144	  const subscription = await subscriptionRepo.updateSubscriptionPlan(
145	    input.orgId,
146	    input.plan,
147	    input.interval,
148	  );
149	
150	  await emit("billing.plan_changed", {
151	    ...actorEnvelope(actor),
152	    from: currentPlan,
153	    to: input.plan,
154	  });
155	
156	  return subscription;
157	}
158	
159	export async function updateSeats(
160	  actor: Actor,
161	  input: UpdateSeatsInput,
162	): Promise<Subscription> {
163	  assertOrgScope(actor, input.orgId);
164	  assertCan(actor, "org:manage_billing", billingResource(input.orgId));
165	
166	  const plan = await planFor(input.orgId);
167	
168	  if (input.seats > getLimit(plan, "seats")) {
169	    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
170	  }
171	
172	  return subscriptionRepo.updateSeatCount(input.orgId, input.seats);
173	}
174	
175	/** Cancels at period end by default; `cancelImmediately` ends it now. */
176	export async function cancelSubscription(
177	  actor: Actor,
178	  input: CancelSubscriptionInput,
179	): Promise<Subscription> {
180	  assertOrgScope(actor, input.orgId);
181	  assertCan(actor, "org:manage_billing", billingResource(input.orgId));
182	
183	  const subscription = requireFound(
184	    await subscriptionRepo.findSubscription(input.orgId),
185	    "Subscription",
186	    input.orgId,
187	  );
188	
189	  return subscriptionRepo.cancelSubscription(
190	    input.orgId,
191	    input.cancelImmediately
192	      ? toIsoTimestamp(new Date())
193	      : subscription.currentPeriodEnd,
194	  );
195	}
196	
197	export async function listInvoices(
198	  actor: Actor,
199	  orgId: OrgId,
200	): Promise<readonly Invoice[]> {
201	  assertOrgScope(actor, orgId);
202	  assertCan(actor, "org:manage_billing", billingResource(orgId));
203	  return invoiceRepo.listInvoices(orgId);
204	}
205	
206	/**
207	 * The subscription row is the authority on which plan an org is on; the
208	 * denormalised `organizations.plan` column is only a display convenience, so
209	 * every quota decision reads the subscription first.
210	 */
211	async function planFor(orgId: OrgId): Promise<PlanId> {
212	  const subscription = await subscriptionRepo.findSubscription(orgId);
213	  if (subscription) return subscription.plan;
214	
215	  const org = requireFound(
216	    await orgRepo.findOrgById(orgId),
217	    "Organization",
218	    orgId,
219	  );
220	  return org.plan;
221	}
222	
223	/** Maps a quota dimension onto the counter that measures it. */
224	async function usageFor(
225	  orgId: OrgId,
226	  resource: LimitedResource,
227	): Promise<number> {
228	  const usage = await usageRepo.getUsage(orgId);
229	
230	  switch (resource) {
231	    case "seats":
232	      return usage.seatsUsed;
233	    case "projects":
234	      return usage.projectsUsed;
235	    case "issuesPerProject":
236	      return usage.issuesUsed;
237	    case "storageMb":
238	      return usage.storageMbUsed;
239	    case "webhooks":
240	      return webhookRepo.countEndpoints(orgId);
241	    case "apiRequestsPerHour":
242	      return 0;
243	  }
244	}
